<script setup lang="ts">const eventId=ref('');const{me,api}=useShowUp();const recent=ref<any>();useLiveRefresh(async()=>{recent.value=me.value?await api('/api/me/diagnostic'):null});function find(){if(eventId.value)navigateTo(`/e/${encodeURIComponent(eventId.value.trim())}`)}</script>
<template><div class="shell"><AppHeader><WalletButton/></AppHeader><main><div class="page-head"><NetworkBadge/><h1>Reserve with NIM. Show up with the same wallet.</h1><p>Get the refund, ticket, or cancellation outcome the host promised.</p></div><section class="panel"><h2>Find an event</h2><label class="field">Event ID<input v-model.trim="eventId" placeholder="Paste the host’s event ID" @keyup.enter="find"></label><button :disabled="!eventId" @click="find">Attend an event</button></section><section class="panel"><h2>Hosting an event?</h2><p>Create a campaign with fixed capacity and payment terms, then run wallet-signed venue check-in.</p><NuxtLink class="button secondary" to="/host">Host an event</NuxtLink></section><section v-if="recent?.reservation" class="panel"><h2>Continue your reservation</h2><NuxtLink class="event-card" :to="`/r/${recent.reservation.id}`"><strong>{{ recent.reservation.title || 'Recent event pass' }}</strong><span>{{ recent.reservation.state }}</span></NuxtLink></section></main></div></template>
